#ifndef __CPU_O3_CHAOS_TRIGGER_HH__
#define __CPU_O3_CHAOS_TRIGGER_HH__

#include <cstdint>
#include "cpu/o3/chaos_event_sample.hh"

namespace gem5
{

/** OoO north-star frequency tiers (docs/gem5-fi/ooo/02-frequency-and-sampling.md). */
enum class ChaOSTier : uint8_t
{
    F0,  // single injection, uniformly random over [first, last)
    F1,  // mean interval 1 ms   ≈ 2,600,000 cycles @2.6GHz
    F2,  // mean interval 100 µs ≈   260,000 cycles
    F3,  // mean interval 10 µs  ≈    26,000 cycles
    F5,  // permanent defect (stuck): active from first use to overwrite/end
};

struct ChaOSTrigger
{
    ChaOSTier tier;
    uint64_t rng;
    uint64_t first_cycle;
    uint64_t last_cycle;   // 0 = unbounded
    uint64_t next_fire;    // next scheduled fire cycle (F0/F1-F3)
    bool     spent;        // F0: already fired
    bool     armed;

    ChaOSTrigger(ChaOSTier t, uint64_t seed, uint64_t first, uint64_t last)
        : tier(t), rng(seed ? seed : 1), first_cycle(first), last_cycle(last),
          next_fire(0), spent(false), armed(false)
    {}

    static constexpr uint64_t
    intervalCycles(ChaOSTier t)
    {
        switch (t) {
          case ChaOSTier::F1: return 2600000;
          case ChaOSTier::F2: return   260000;
          case ChaOSTier::F3: return    26000;
          default:            return        0;
        }
    }

    uint64_t nextU01()  // uniform [0, 2^64) -> [0,1)
    {
        rng = chaosSampleLCG(rng);
        return rng;
    }

    bool fire(uint64_t now)
    {
        switch (tier) {
          case ChaOSTier::F5:
            return true;                      // permanent defect
          case ChaOSTier::F0: {
            if (spent) return false;
            if (!armed) {                     // draw the uniform landing cycle
                armed = true;
                uint64_t span = (last_cycle > first_cycle)
                              ? last_cycle - first_cycle : 1;
                next_fire = first_cycle + nextU01() % span;
            }
            if (now >= next_fire) { spent = true; return true; }
            return false;
          }
          case ChaOSTier::F1:
          case ChaOSTier::F2:
          case ChaOSTier::F3: {
            if (!armed) {
                armed = true;
                scheduleNext(first_cycle);
            }
            if (now < next_fire) return false;
            scheduleNext(next_fire);          // jitter the NEXT interval
            return true;
          }
        }
        return false;
    }

  private:
    void scheduleNext(uint64_t from)
    {
        // jitter ±50%: interval * U(0.5, 1.5)
        // U01 via multiply: (interval/2) + nextU01() % interval
        uint64_t iv = intervalCycles(tier);
        next_fire = from + iv / 2 + nextU01() % iv;
    }
};

} // namespace gem5

#endif
